"""The nine S1 (planned surgery) P0 cases: A, PB, E, B, C, D, G, H, J. Source: walkthrough Part 11 (steps), Part 12 and Part 17; see content/case_seeds.csv for the story of each.

Everything the book states is marked origin 'book'; the rest is authored (see content/case_files_authoring.csv) and stays inside the verified bands, with no doses.
"""
from lib import D, E, H, O, P, R, S, bad, case, debrief, history, person

CASES = {}

# ---------------------------------------------------------------------------------------------------------------- VAR-S1-A
CASES["VAR-S1-A"] = case(
    "VAR-S1-A", "Example Patient A - uncomplicated S1 (everything goes right)", "S1",
    person("Mrs", "Ayesha Khan", "F", 42, "teacher", 3, 14, "102938", dob="1984-03-14"),
    {"setting": "pre-assessment", "time_now": "08:00", "surgery_time": "09:00",
     "summary": "A fit 42-year-old teacher booked for planned keyhole gallbladder removal at 09:00. Nothing is wrong today: the case teaches careful confirmation without over-investigating."},
    [H("complaint", "Attacks under my right ribs after oily food, settle in an hour or two. None in the last 3 weeks.", True, "book"),
     H("red_flags", "No fever, no yellow eyes, urine normal colour, no back pain.", origin="book"), H("past_history", "None.", origin="book"), H("medicines", "None except paracetamol sometimes.", origin="book"),
     H("herbal", "None.", origin="book"), H("previous_anaesthetic", "Caesarean section 2012, no problems.", origin="book"), H("family_anaesthetic", "No anaesthetic problems.", origin="book"),
     H("smoking", "Never.", origin="book"), H("alcohol", "None.", origin="book"), H("last_food", "Dinner at 21:00 last night (rice and chicken).", origin="book"),
     H("last_drink", "Water at 06:30.", origin="book"),
     H("pregnancy", "Last period started 10 days ago; she uses a coil. She agrees to a urine pregnancy test (hospital policy).", origin="book")],
    [O("08:00", 76, 124, 78, 14, 98, 36.7, note="Baseline vital signs; every value in the normal band.")],
    [E("ex.eyes", "eyes", "Whites of the eyes are white; no jaundice.", False, "book"), E("ex.chest", "chest", "Heart and lungs sound normal.", False, "book"),
     E("ex.abdomen", "abdomen", "Tummy soft; mild tenderness under the right ribs, only with deep pressure.", False, "book"), E("ex.murphy", "murphy", "Murphy's sign negative.", False, "book"),
     E("ex.mouth", "airway", "Mouth opens well (3 fingers).", False, "book", ["airway_check:mouth_opening"]), E("ex.mallampati", "airway", "Mallampati class 2.", False, "book", ["airway_check:mallampati"]),
     E("ex.neck", "airway", "Neck moves normally.", False, "book", ["airway_check:neck"])],
    [R("lab.bilirubin", "Bilirubin", 12, "umol/L", "3-21", comment="Bile flowing normally", origin="book", row="SR-2400"),
     R("lab.alt", "ALT", 24, "U/L", "7-40", comment="Liver cells fine", origin="book", row="SR-2401"),
     R("lab.alp", "ALP", 78, "U/L", "30-130", comment="Bile ducts not blocked", origin="book", row="SR-2402"),
     R("lab.ggt", "GGT", 22, "U/L", "below 40 (women)", comment="Confirms ducts fine", origin="book", row="SR-2403"),
     R("lab.albumin", "Albumin", 42, "g/L", "35-50", comment="Good nutrition", origin="book", row="SR-2404"),
     R("lab.upt", "Urine pregnancy test", "Negative", "", "negative", "negative", "Not pregnant", origin="book", row="SR-2405")],
    [S("NEWS2", "0", "Computed from the baseline vital signs", "book")],
    [P("a.nothing", "information_only", "Nothing abnormal: the patient is fit and fasted", 1, "The task is to confirm identity, allergies, fasting and the usual tests without inventing problems.",
       ["Complete the identity check against the wristband and the notes", "Confirm there are no allergies", "Check fasting times", "Do the liver tests and the urine pregnancy test"]),
     P("a.blockers", "safety_blocker", "Identity, allergy, consent and pregnancy-status checkpoints", 2, "No transfer until each checkpoint is closed.", ["Close each checkpoint before transfer"])],
    [D("a.d1", "Which extra tests does Mrs Khan need before surgery?",
       [("Only the liver tests and the pregnancy test: she is healthy and under 65, so chest X-ray, ECG, clotting and kidney tests would not change anything", True, "Matches the book: routine extra tests are not ordered."),
        ("Chest X-ray, ECG, clotting and kidney tests as well", False, "Not harmful, but none would change management; the debrief notes the wasted time.")], rule=None),
     D("a.d2", "Is she fasted enough for 09:00?",
       [("Yes: last solid food was about 12 hours ago and her last water 2.5 hours ago", True, "Within the 6 hour and 2 hour rules."), ("No: postpone", False, "Unnecessary delay.")], rule="fasting_planned"),
     D("a.d3", "Proceed to theatre?", [("Yes: safe to continue", True, "End state: ready for incision."), ("Postpone", False, "No reason to postpone.")])],
    "ready",
    {"correct": ["Check identity: spoken name and date of birth, wristband, notes", "Allergies: none", "Short history including the red flags and fasting times", "Baseline vital signs, NEWS2 0",
                 "Liver tests and urine pregnancy test", "Report to the anaesthetist; proceed"],
     "incorrect": [bad("Orders chest X-ray, ECG, clotting and kidney tests", "Results all normal; time passes", "Delay and cost with no benefit", "Stop ordering; proceed once the standard checks are done")],
     "missed": ["Skipping the urine pregnancy test (hospital policy) leaves the pregnancy status undocumented at Sign In"], "recovery": ["Do the test late; document; tell the anaesthetist"]},
    debrief(["Identity matched in three places", "Fasting times adequate", "No unnecessary tests"], ["Pregnancy status not documented"], "Confirm identity, allergies and fasting",
            "Wrong-patient and fasting errors are the most serious avoidable harms", "The checks are independent", "Nothing in this case is connected: it is a clean pass", "Any mismatch in identity or an unknown allergy",
            "Not applicable: the case ends well", "A normal patient still needs every check; do not invent problems"),
    ["V-09"], reason="To have my gallbladder taken out with keyhole.", base_card="VAR-S1-A")

# ---------------------------------------------------------------------------------------------------------------- VAR-S1-PB
CASES["VAR-S1-PB"] = case(
    "VAR-S1-PB", "Example Patient B - abnormal S1 (the 'elective' patient who isn't well today)", "S1",
    person("Mrs", "Farzana Ahmed", "F", 61, "retired shopkeeper", 8, 21, "205814"),
    {"setting": "pre-assessment", "time_now": "08:00", "surgery_time": "09:00",
     "summary": "Mrs Ahmed, 61, is booked for planned keyhole gallbladder removal. Her daughter noticed yellow eyes last week and she has dark urine: a stone may have moved into the main bile duct."},
    history("Some aching under the ribs on and off.", red_flags="My daughter said my eyes looked a bit yellow last week. And my urine has been dark like tea. No fever or shivering.", past="Gallstones, found on a scan last year.",
            medicines="Paracetamol when the pain comes.", last_food="Tea and a biscuit yesterday evening at 20:00, nothing since.", last_drink="Water at 06:00.", pregnancy="Not applicable (past the menopause).",
            origin={"complaint": "book", "red_flags": "book"}),
    [O("08:00", 84, 138, 84, 16, 97, 37.2, pain=2, note="No fever: probably no infection in the duct (yet).")],
    [E("ex.eyes", "eyes", "Yellow tinge to the whites of the eyes.", True, "book"), E("ex.abdomen", "abdomen", "Mild tenderness under the right ribs; no guarding; no lump."),
     E("ex.skin", "skin", "Skin is not itchy-scratched; no rash.")],
    [R("lab.bilirubin", "Bilirubin", 72, "umol/L", "3-21", "high", "HIGH (above 68): bile is backing up", ("14", "pre-assessment 6 weeks ago"), 45, origin="book", row="SR-2412"),
     R("lab.alp", "ALP", 380, "U/L", "30-130", "high", "About 3 times normal: bile duct cells irritated by blockage", ("118", "pre-assessment 6 weeks ago"), 45, origin="book", row="SR-2413"),
     R("lab.ggt", "GGT", 410, "U/L", "below 40", "high", "Confirms the ALP is coming from the bile system", ("35", "pre-assessment 6 weeks ago"), 45, origin="book", row="SR-2414"),
     R("lab.alt", "ALT", 160, "U/L", "7-40", "high", "Moderately raised: liver cells irritated by backed-up bile", ("32", "pre-assessment 6 weeks ago"), 45, origin="book", row="SR-2415"),
     R("lab.wbc", "WBC", 9.8, "x10^9/L", "4.0-11.0", "normal", "Normal: no strong sign of infection", None, 45, origin="book", row="SR-2416"),
     R("lab.crp", "CRP", 12, "mg/L", "below 5", "high", "Mildly raised", None, 45, origin="book", row="SR-2417"),
     R("lab.inr", "INR", 1.1, "ratio", "0.8-1.2", "normal", "Clotting normal (a long blockage could raise it)", None, 45, origin="book", row="SR-2418"),
     R("lab.lipase", "Lipase", 45, "U/L", "below 60", "normal", "Pancreas not inflamed", None, 45, origin="book", row="SR-2419")],
    [S("NEWS2", "0", "Computed from the vital signs", "book"), S("Bile-duct-stone risk", "High", "Bilirubin above 68 micromol/L plus a duct wider than 6 mm (ASGE 2019)", "book")],
    [P("pb.stone", "pathway_changing", "Probable stone in the main bile duct: not what she was booked for", 1,
       "Jaundice, cholestatic liver tests and a 9 mm duct make a duct stone likely; operating on the gallbladder alone would leave it in place.",
       ["Ask the red-flag questions and look at her eyes", "Request liver tests and an ultrasound", "Score the risk: high", "Do not proceed today; call the senior surgeon"]),
     P("pb.cholangitis", "time_critical", "Watch for infection of the duct (cholangitis)", 2, "No fever, shivering or low BP today, but it can develop.",
       ["Check temperature, pulse and BP again", "Give her safety-net advice: fever, shivering or worse pain means come straight back"])],
    [D("pb.d1", "Bilirubin 72 and the bile duct is 9 mm on ultrasound. What now?",
       [("High risk of a duct stone: do not proceed today, call the senior surgeon, plan ERCP before the gallbladder operation", True, "Matches the book and ASGE 2019."),
        ("Proceed with today's operation", False, "The stone would stay in the duct: risk of cholangitis or pancreatitis."),
        ("Proceed and order an MRCP afterwards", False, "MRCP is for intermediate risk before the operation; this is high risk.")], rule="duct_stone_high_risk"),
     D("pb.d2", "Is there any sign of cholangitis today (fever, shivering, low BP)?",
       [("No: she has no fever, normal BP and pulse", True, "Not the emergency branch; the high-risk pathway applies."), ("Yes: start the sepsis bundle", False, "Not supported by her observations.")]),
     D("pb.d3", "What safety-net advice do you give Mrs Ahmed?",
       [("If you get a fever, shivering or worse pain, come straight back: it could be an infection in the duct", True, "Correct."), ("No advice is needed", False, "The risk of infection remains until the stone is cleared.")])],
    "postponed",
    {"correct": ["Ask the red-flag questions: yellow eyes, dark urine, fever, pain", "Examine the eyes: jaundice confirmed", "Vital signs; liver tests; ultrasound", "Risk tool: high", "Stop today's plan; senior; ERCP pathway",
                 "Explain to Mrs Ahmed, document, safety-net advice"],
     "incorrect": [bad("Ignores the abnormal liver tests and goes ahead", "The senior or anaesthetist character stops the case", "Stone left in the duct", "Review the results and call the senior")],
     "missed": ["Does not ask about yellow eyes or look: the liver tests (if ordered) still flag it"], "recovery": ["Recognise from the tests, then call the senior"]},
    debrief(["Jaundice picked up from the history and examination", "High risk correctly scored", "Planned operation stopped"], ["Not asking the red-flag questions"], "A probable duct stone in a planned patient",
            "It changes the whole pathway", "Jaundice, cholestatic tests and the wide duct all come from the same blocked duct", "None: the findings are linked", "Yellow eyes, dark urine, abnormal liver tests",
            "A stone left in the duct can cause life-threatening infection", "Ask about yellow eyes in every gallstone patient"),
    ["V-03"], reason="To have my gallbladder taken out.")

# ---------------------------------------------------------------------------------------------------------------- VAR-S1-E
CASES["VAR-S1-E"] = case(
    "VAR-S1-E", "Patient S1-E - the planned patient with an inflamed gallbladder", "S1",
    person("Mrs", "Rabia Siddiqui", "F", 48, "bank clerk", 5, 9, "311207"),
    {"setting": "pre-assessment", "time_now": "08:00", "surgery_time": "10:30",
     "summary": "Mrs Rabia, 48, booked for planned gallbladder removal, arrives with constant pain for 2 days and felt hot overnight: she now has an acute illness."},
    history("Constant pain under the right ribs for two days; I felt hot and shivery overnight.", red_flags="No yellow eyes. Urine normal colour.", past="Gallstones.", medicines="Paracetamol.",
            last_food="Dry toast yesterday at noon; nothing since because of the pain.", last_drink="Sips of water at 05:00.", pregnancy="Last period 3 weeks ago; she agrees to a test.", origin={"complaint": "book"}),
    [O("08:00", 108, 118, 72, 20, 97, 38.4, pain=6, note="NEWS2 2 as the book states: HR 108 (1) + T 38.4 (1).")],
    [E("ex.murphy", "murphy", "Tender under the right ribs; Murphy's sign positive.", True, "book"), E("ex.abdomen", "abdomen", "Tender under the right ribs; no guarding elsewhere; no palpable lump."),
     E("ex.eyes", "eyes", "No jaundice.")],
    [R("lab.wbc", "WBC", 15.2, "x10^9/L", "4.0-11.0", "high", "Raised: whole-body inflammation (not above 18)", ("6.8", "pre-assessment 6 weeks ago"), 45, origin="book", row="SR-2443"),
     R("lab.crp", "CRP", 96, "mg/L", "below 5", "high", "Raised: whole-body inflammation", ("4", "pre-assessment 6 weeks ago"), 45, origin="book", row="SR-2443"),
     R("lab.upt", "Urine pregnancy test", "Negative", "", "negative", "negative", "Not pregnant", None, 20)],
    [S("NEWS2", "2", "HR 108 (1) + T 38.4 (1) as the book states; recomputed", "book"), S("Tokyo 2018 grade", "I (mild)", "WBC 15.2 not above 18; symptoms under 72 hours; no mass; no organ failure", "book")],
    [P("e.cholecystitis", "pathway_changing", "Acute cholecystitis (inflamed gallbladder), definite by Tokyo 2018", 1,
       "A planned patient with local signs (Murphy's), systemic inflammation (WBC, CRP, fever) and a scan with a thick wall and fluid is no longer a routine list patient.",
       ["Recognise A (local signs), B (systemic signs) and C (imaging)", "Grade it: Grade I", "Do not take her on today's planned list as a routine case", "Senior surgeon review; antibiotics per protocol; move to the acute pathway"])],
    [D("e.d1", "Mrs Rabia has fever, a positive Murphy's sign, WBC 15.2, CRP 96 and a scan with a 6 mm wall and fluid. What now?",
       [("She has acute cholecystitis (Grade I): not suitable for the routine list; senior review, antibiotics and the acute pathway", True, "Matches the book; early keyhole surgery is usually the plan."),
        ("Proceed with the planned operation as booked", False, "She is acutely ill; the elective pathway no longer applies."),
        ("Send her home on tablets", False, "Fever and raised inflammatory markers need review today.")], rule="gallbladder_moderate_grade")],
    "redirected",
    {"correct": ["Notice fever and tachycardia in a planned patient", "Examine: Murphy's positive", "Blood tests: WBC and CRP", "Ultrasound: wall 6 mm, fluid", "Tokyo grade I", "Call the senior; acute pathway"],
     "incorrect": [bad("Continues the list", "The anaesthetist finds T 38.4 at Sign In", "An acutely infected patient anaesthetised as elective", "Stop and escalate")],
     "missed": ["Does not take a temperature: the inflammation is missed until the anaesthetist checks"], "recovery": ["Repeat vital signs, send bloods, call the senior"]},
    debrief(["Fever and tachycardia noticed", "Tokyo A, B and C combined", "Pathway changed"], ["Not examining the abdomen"], "Acute cholecystitis in a planned patient", "The pathway changes from elective to acute",
            "Local signs, systemic signs and the scan fit together", "None", "Fever in a planned patient", "Worsening infection and a delayed operation", "Planned patients can arrive unwell: always take the temperature"),
    ["V-06", "V-01"], reason="To have my gallbladder taken out, but the pain is bad today.")

# ---------------------------------------------------------------------------------------------------------------- VAR-S1-B
CASES["VAR-S1-B"] = case(
    "VAR-S1-B", "Patient S1-B - high blood pressure", "S1",
    person("Mr", "Tariq Mahmood", "M", 58, "taxi driver", 1, 23, "412330"),
    {"setting": "pre-assessment", "time_now": "08:00", "surgery_time": "10:00",
     "summary": "Mr Tariq, 58, on blood pressure tablets, has no GP blood pressure readings in his letter. First reading 172/104; after 5 minutes' rest 168/102. A second variant has 188/114 and 186/112."},
    history("A bit of indigestion after fatty meals; no pain today.", red_flags="No headache, no chest pain, no breathlessness, no change in vision.", past="High blood pressure for six years.",
            medicines="A blood pressure tablet each morning; he took it today.", last_food="Dinner at 20:00 yesterday.", last_drink="Water at 06:30.", pregnancy="Not applicable.", origin={"complaint": "authored"}),
    [O("08:00", 80, 172, 104, 16, 97, 36.8, note="First reading 172/104.", origin="book"), O("08:06", 78, 168, 102, 16, 97, 36.8, note="Repeat after 5 minutes' rest and correct cuff size: 168/102.", origin="book"),
     O("08:00", 82, 188, 114, 16, 97, 36.8, cond="variant", note="Variant B2: 188/114 then 186/112 on repeat: above the limit.", origin="book"),
     O("08:06", 80, 186, 112, 16, 97, 36.8, cond="variant", note="Variant B2 repeat.", origin="book")],
    [E("ex.cvs", "heart", "Regular pulse; heart sounds normal; no ankle swelling."), E("ex.fundi", "eyes", "No visible eye signs of organ damage at the bedside.")],
    [R("lab.ecg", "ECG", "Sinus rhythm, no acute change", "", "sinus rhythm", "normal", "Routine for treated hypertension", None, 20)],
    [S("NEWS2", "0", "Heart rate 78, BP 168 (NEWS2 gives 0 for 111 to 219), other values normal", "book"), S("Blood pressure grade", "Grade 2 (160 to 179 / 100 to 109)", "Below the 180/110 postpone limit", "book")],
    [P("b.bp", "information_only", "Blood pressure high but below 180/110 and no organ-damage symptoms", 1, "Rule (AAGBI/BHS, V-07; Hartle 2016): below 180/110 in clinic, surgery proceeds; the GP reviews afterwards. It is recorded and handed over, not a reason to stop.",
       ["Repeat the reading properly (rest, right cuff)", "Ask about headache, chest pain, breathlessness, vision", "Compare with 180/110", "Tell the anaesthetist"], variant="base"),
     P("b.bp2", "optimisable", "Blood pressure 188/114 and 186/112 on repeat: above the 180/110 limit", 2, "Rule (AAGBI/BHS, V-07; Hartle 2016): a clinic reading of 180/110 or more is unsuitable for elective surgery: postpone and refer back for control; do not try to lower it quickly.",
       ["Repeat after rest with the right cuff", "Postpone the planned surgery", "Refer to the GP for control"], variant="B2")],
    [D("b.d1", "168/102 on repeat, no symptoms of organ damage. What now?",
       [("Surgery can proceed: tell the anaesthetist and ask the GP to review the blood pressure after surgery", True, "Below 180/110: proceed (variant B1)."),
        ("Postpone and send him back to the GP", False, "Not required below 180/110."), ("Give a drug to bring it down quickly before theatre", False, "Rapid lowering is not done to make surgery possible.")], rule="s1_bp_postpone"),
     D("b.d2", "Variant B2: 188/114 and 186/112 on repeat. What now?",
       [("Postpone and refer for control; do not try to drop the pressure rapidly today", True, "At or above 180/110 the planned operation is deferred."), ("Proceed as for B1", False, "Above the limit.")], rule="s1_bp_postpone")],
    "ready",
    {"correct": ["Repeat after 5 minutes' rest with the right cuff", "Ask about symptoms of organ damage", "Compare with 180/110", "B1: proceed and tell the anaesthetist; B2: postpone and refer"],
     "incorrect": [bad("Treats a single high reading as real without repeating", "Repeat is lower", "Needless postponement", "Repeat the reading properly"), bad("Lowers the pressure rapidly with a drug", "BP drops and he becomes dizzy", "Harm from rapid lowering", "Stop; observe")],
     "missed": ["Not asking about headache, chest pain or breathlessness"], "recovery": ["Ask now; if symptomatic, escalate"]},
    debrief(["Reading repeated properly", "Threshold applied"], ["Symptom questions"], "Decide proceed or postpone from the repeated reading and symptoms", "The limit is 180/110 in clinic", "Reading, symptoms and the limit work together", "None",
            "180/110 or above, or symptoms of organ damage", "Needless postponement, or harm from forcing the pressure down", "Repeat before you act; the limit is 180/110"),
    ["V-07"], reason="To have my gallbladder taken out.", variant_end={"B2": "postponed"})
